% This test file was generated by Copilot. Validate generated output before use.
classdef TestLoadFlightData < matlab.unittest.TestCase
    methods(Test)
        function testLoadsSingleRowWorkbook(testCase)
            % Test that the function imports a workbook into a table with the expected variables.
            workbookFile = "FlightData.xlsx";

            sourceTable = table( ...
                datetime(2024,1,1,12,0,0), ...
                100, 30, 200, 37.5, -122.3, 35000, 500, 2500, 90, 450, 180, 15, ...
                'VariableNames', ["Time","FuelQuantity","OilPressure","OilTemperature", ...
                "LatitudePosition","LongitudePosition","Altitude","ExhaustTemperature", ...
                "FuelFlow","FanSpeed","TrueAirSpeed","WindDirection","WindSpeed"]);

            flightData = loadFlightData(workbookFile);

            testCase.verifyClass(flightData, "table");
            testCase.verifyEqual(flightData.Properties.VariableNames, sourceTable.Properties.VariableNames);
        end

        function testLoadsMultipleRowsWorkbook(testCase)
            % Test that the function imports multiple rows and preserves the data order.
            workbookFile = "FlightData.xlsx";
            flightData = loadFlightData(workbookFile);
            

            testCase.verifyEqual(height(flightData), 47312);
        end
    end
end